def _ipv4_to_bytes(ip_address):
    parts = str(ip_address).split(".")
    if len(parts) != 4:
        raise Exception(f"Invalid IPv4 address: {ip_address}")

    result = []
    for part in parts:
        value = int(part)
        if value < 0 or value > 255:
            raise Exception(f"IPv4 value is out of range: {ip_address}")
        result.append(value)
    return result


def _parse_bit(value):
    text = str(value).strip()
    if text not in ("0", "1"):
        raise Exception(f"Bit value must be 0 or 1: {value}")
    return int(text)


def _parse_group_value(value, width):
    text = str(value).strip()
    if text.lower().endswith("b"):
        text = text[:-1]
    if text.lower().startswith("0b"):
        parsed = int(text, 2)
    elif set(text) <= {"0", "1"} and len(text) > 1:
        parsed = int(text, 2)
    elif text.lower().startswith("0x"):
        parsed = int(text, 16)
    else:
        parsed = int(text)

    if parsed < 0 or parsed > ((1 << width) - 1):
        raise Exception(f"Bit group value does not fit in {width} bit(s): {value}")
    return parsed


def _bit_group_to_pairs(value, bits):
    parsed = _parse_group_value(value, len(bits))
    result = []
    for offset, bit_position in enumerate(sorted(bits)):
        result.append((bit_position, (parsed >> offset) & 0x01))
    return result


